p='tasarim/karsilama-yol/prototip.html'; s=open(p,encoding='utf-8').read()
i=s.find('<script>'); j=s.find('</script>')+len('</script>')
yeni_script = r'''<script>
  // ---------- yol: duz bir giris parcasi + bes cubic kivrim, asagidan yukariya ----------
  // Ilk parca DUZ (195,2150)->(195,1850): referansta iz simgeden asagiya
  // dumduz uzuyor; simge o parcanin ucunda (P0) baslar.
  const PARCALAR = [
    [[195,2150],[195,2050],[195,1950],[195,1850]],
    [[195,1850],[195,1750],[300,1720],[300,1600]],
    [[300,1600],[300,1480],[90,1470],[90,1350]],
    [[90,1350],[90,1230],[300,1220],[300,1100]],
    [[300,1100],[300,980],[90,970],[90,850]],
    [[90,850],[90,730],[195,700],[195,600]],
  ]
  // donemecler: kivrim uclari; etiket yolun KARSI tarafinda, cizgiden uzak
  const DONEMEC = [
    { p: [300,1600], taraf: 'sol' }, { p: [90,1350], taraf: 'sag' },
    { p: [300,1100], taraf: 'sol' }, { p: [90,850], taraf: 'sag' },
  ]
  function bez(P, t) { const u = 1 - t; return [
    u*u*u*P[0][0] + 3*u*u*t*P[1][0] + 3*u*t*t*P[2][0] + t*t*t*P[3][0],
    u*u*u*P[0][1] + 3*u*u*t*P[1][1] + 3*u*t*t*P[2][1] + t*t*t*P[3][1] ] }
  const NOKTA = [], UZ = [0]
  for (const P of PARCALAR) for (let i = 0; i <= 60; i++) { if (NOKTA.length && i === 0) continue; NOKTA.push(bez(P, i / 60)) }
  for (let i = 1; i < NOKTA.length; i++) { const a = NOKTA[i-1], b = NOKTA[i]; UZ.push(UZ[i-1] + Math.hypot(b[0]-a[0], b[1]-a[1])) }
  const TOPLAM = UZ[UZ.length - 1]
  function indeksAt(ilerleme) { const hedef = ilerleme * TOPLAM; let lo = 0, hi = UZ.length - 1
    while (lo < hi) { const m = (lo + hi) >> 1; if (UZ[m] < hedef) lo = m + 1; else hi = m } return Math.max(1, lo) }
  function noktaAt(ilerleme) {
    const hedef = ilerleme * TOPLAM, i = indeksAt(ilerleme), a = NOKTA[i-1], b = NOKTA[i], s = (UZ[i] - UZ[i-1]) || 1, k = Math.min(1, Math.max(0, (hedef - UZ[i-1]) / s))
    return { x: a[0] + (b[0]-a[0]) * k, y: a[1] + (b[1]-a[1]) * k, i }
  }
  const enYakinIlerleme = (p) => { let en = 0, enUz = 1e9; NOKTA.forEach((n, i) => { const u = Math.hypot(n[0]-p[0], n[1]-p[1]); if (u < enUz) { enUz = u; en = i } }); return UZ[en] / TOPLAM }
  const P0 = enYakinIlerleme([195,1850])                 // simgenin baslangici (duz parcanin ucu)
  const DONEMEC_ILERLEME = DONEMEC.map(d => enYakinIlerleme(d.p))
  const yolDizisi = (nok) => nok.length > 1 ? 'M' + nok.map(n => n[0].toFixed(1) + ' ' + n[1].toFixed(1)).join(' L') : ''

  const svgYol = document.getElementById('yol'), yolGri = document.getElementById('yolGri'), turuncu = document.getElementById('yolTuruncu')
  yolGri.setAttribute('d', yolDizisi(NOKTA))
  const noktalar = document.getElementById('noktalar')
  DONEMEC.forEach(k => { const c = document.createElementNS('http://www.w3.org/2000/svg','circle'); c.setAttribute('cx', k.p[0]); c.setAttribute('cy', k.p[1]); c.setAttribute('r', 4); c.setAttribute('fill', '#FAF7F3'); c.setAttribute('stroke', '#E2DAD2'); c.setAttribute('stroke-width', 1.6); noktalar.appendChild(c) })
  // etiketler: cizgiden 58 px uzakta, donemecin hizasinda dikey ortali
  DONEMEC.forEach((k, i) => { const e = document.getElementById('e' + i)
    if (k.taraf === 'sol') { e.style.right = (390 - k.p[0] + 58) + 'px'; e.style.width = (k.p[0] - 58 - 20) + 'px' }
    else { e.style.left = (k.p[0] + 58) + 'px'; e.style.width = (390 - k.p[0] - 58 - 20) + 'px' }
    e.style.top = (k.p[1] - 34) + 'px' })

  // ---------- zamanlama: giris, sonra bacak + duraklama ----------
  const GIRIS_TEK = 900, GIRIS_IZ = 700, BACAK = 1500, DURAK = 850
  // anahtar kareler: [baslangicMs, bitisMs, ilerlemeBas, ilerlemeSon]
  const KARELER = []; let t = GIRIS_TEK + GIRIS_IZ, onceki = P0
  const hedefler = [...DONEMEC_ILERLEME, 1]
  hedefler.forEach((h, i) => { KARELER.push([t, t + BACAK, onceki, h]); t += BACAK; onceki = h; if (i < hedefler.length - 1) { KARELER.push([t, t + DURAK, h, h]); t += DURAK } })
  const TOPLAM_SURE = t
  const easeInOut = x => x < .5 ? 2*x*x : 1 - Math.pow(-2*x + 2, 2) / 2
  const easeOut = x => 1 - Math.pow(1 - x, 3)
  function ilerlemeAt(ms) { if (ms < KARELER[0][0]) return P0
    for (const [b, e, p, q] of KARELER) if (ms < e) return p + (q - p) * easeInOut((ms - b) / (e - b))
    return 1 }

  const ekran = document.querySelector('.ekran'), dunya = document.getElementById('dunya'), simge = document.getElementById('simge')
  const son = document.getElementById('son'), atla = document.getElementById('atla')
  const azHareket = matchMedia('(prefers-reduced-motion: reduce)').matches
  let bas = 0, bitti = false, raf = 0
  const olcek = () => ekran.clientWidth / 390

  function ciz(ilerleme, izBas, yolOpak) {
    const { x, y, i } = noktaAt(ilerleme), o = olcek()
    simge.style.left = (x * o) + 'px'; simge.style.top = (y * o) + 'px'
    // gecilen iz: izBas'tan simgeye (giriste izBas P0'dan 0'a iner - asagiya dogru cizilir)
    const iB = indeksAt(izBas), nb = noktaAt(izBas)
    const iz = [[nb.x, nb.y]].concat(NOKTA.slice(iB, i)).concat([[x, y]])
    turuncu.setAttribute('d', izBas < ilerleme - 1e-4 ? yolDizisi(iz) : '')
    yolGri.style.opacity = yolOpak; noktalar.style.opacity = yolOpak
    // kamera: simge ekranin %52'sinde
    let ty = ekran.clientHeight * 0.52 - y * o
    ty = Math.min(ekran.clientHeight * 0.52 - 600 * o + 0, ty) // yol basi ekranin ustune sabitlenmez
    dunya.style.transform = `translateY(${ty}px)`
    DONEMEC_ILERLEME.forEach((p, k) => { document.getElementById('e' + k).classList.toggle('acik', ilerleme > p - 0.045 && ilerleme < p + 0.09) })
  }

  function adim(ts) {
    if (!bas) bas = ts
    const ms = ts - bas
    if (ms < GIRIS_TEK) ciz(P0, P0, 0)
    else if (ms < GIRIS_TEK + GIRIS_IZ) { const k = easeOut((ms - GIRIS_TEK) / GIRIS_IZ); ciz(P0, P0 * (1 - k), k) }
    else ciz(ilerlemeAt(ms), 0, 1)
    if (ms < TOPLAM_SURE) raf = requestAnimationFrame(adim); else bitir()
  }

  function bitir() {
    if (bitti) return; bitti = true; cancelAnimationFrame(raf)
    ciz(1, 0, 1)
