  zeminRenk: {
    position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
    backgroundColor: 'rgba(23, 19, 15, 0.55)',
  },
  zemin: { flex: 1, justifyContent: 'flex-end' },
